const architectureDrafts={};
const architectureToolOptions={Server:['AWS','Azure','Google Cloud','On-premises'],Backend:['Laravel','Node.js','Django','Spring Boot'],Frontend:['React','Next.js','Vue','Angular'],Database:['PostgreSQL','MySQL','MongoDB'],Infrastructure:['Docker','Redis','Object storage','Managed database']};
function architectureDraft(){return architectureDrafts[selected] ||= {prompt:'',budget:'',currency:'USD',basis:'Monthly infrastructure',tools:{},status:'Draft',feedback:[],result:null};}
function changeArchitectureInput(key,value){const d=architectureDraft();d[key]=value;d.status='Draft';architectureState().approved=false;}
function architectureToolsDialog(){const d=architectureDraft(),box=document.getElementById('modal');box.className='history-dialog';box.innerHTML='<form onsubmit="saveArchitectureTools(event)"><div class="history-heading"><h2>Choose architecture tools</h2></div><div class="history-body form">'+Object.entries(architectureToolOptions).map(([group,options])=>'<fieldset class="architecture-tool-group"><legend>'+group+'</legend>'+options.map(tool=>'<label><input type="checkbox" name="'+group+'" value="'+tool+'" '+((d.tools[group]||[]).includes(tool)?'checked':'')+'>'+tool+'</label>').join('')+'</fieldset>').join('')+'</div><div class="history-footer"><button type="button" onclick="document.getElementById(\'modal\').close()">Cancel</button><button class="primary">Apply tools</button></div></form>';box.showModal();}
function saveArchitectureTools(e){e.preventDefault();const f=new FormData(e.target);changeArchitectureInput('tools',Object.fromEntries(Object.keys(architectureToolOptions).map(k=>[k,f.getAll(k)])));document.getElementById('modal').close();render();}
function generateConfiguredArchitecture(e){e.preventDefault();const id=selected,d=architectureDraft();const context={prompt:d.prompt,budget:d.budget,currency:d.currency,basis:d.basis,tools:JSON.parse(JSON.stringify(d.tools)),requirements:JSON.parse(JSON.stringify(backlog().rows)),timeline:timelineGenerationContexts[id]||null,feedback:d.feedback.map(f=>f.text)};const overlay=document.createElement('div');overlay.className='workflow-loading';overlay.innerHTML='<span class="workflow-spinner"></span><b>Preparing architecture…</b>';document.body.append(overlay);setTimeout(()=>{try{const components=Object.fromEntries(Object.keys(architectureToolOptions).map(k=>[k,(context.tools[k]||[]).join(' / ')||'To be selected']));d.result={context,components,time:new Date().toISOString()};d.status='In review';if(selected===id){architectureState().approved=false;architectureState().doc=Object.entries(components).map(([k,v])=>k+': '+v).join('\n')+'\n\nInstructions: '+(context.prompt||'None provided')+'\nBudget: '+(context.budget===''?'Not specified':context.currency+' '+context.budget+' · '+context.basis)+'\n\nIllustrative draft. AI generation and provider cost estimates are not connected; budget feasibility is not verified.';captureProjectVersion('architecture','Architecture draft generated');render();}}finally{overlay.remove();}},800);}
function architectureDecision(approve){const d=architectureDraft();if(!d.result||d.status==='Draft')return toast('Generate the architecture with your latest inputs first.');if(approve){d.status='Approved';architectureState().approved=true;captureProjectVersion('architecture','Architecture approved');render();return;}const box=document.getElementById('modal');box.className='history-dialog';box.innerHTML='<form onsubmit="rejectArchitecture(event)"><div class="history-heading"><h2>Disapprove architecture</h2></div><div class="form"><label class="field">Feedback<textarea name="feedback" required maxlength="4000" placeholder="Explain the changes needed"></textarea></label></div><div class="history-footer"><button type="button" onclick="document.getElementById(\'modal\').close()">Cancel</button><button class="request-stop">Disapprove</button></div></form>';box.showModal();box.querySelector('textarea').focus();}
function rejectArchitecture(e){e.preventDefault();const text=String(new FormData(e.target).get('feedback')||'').trim();if(!text)return;const d=architectureDraft();d.status='Disapproved';d.feedback.push({text,author:profile.name,time:new Date().toISOString()});architectureState().approved=false;captureProjectVersion('architecture','Architecture disapproved');document.getElementById('modal').close();render();}
function continueArchitectureTests(){if(architectureDraft().status!=='Approved')return toast('Approve the architecture first.');navigate('tests');}
blueprintPageRoutes.architecture=function(){if(!selected)return missingProject();const d=architectureDraft(),ready=d.result&&d.status!=='Draft';const actions=(d.result?button('Export design','exportArchitecture()'):'')+button('Version history',"showProjectHistory('architecture')")+'<button class="request-stop" '+(ready?'':'disabled')+' onclick="architectureDecision(false)">Disapprove</button><button class="primary" '+(ready?'':'disabled')+' onclick="architectureDecision(true)">Approve</button>'+(d.status==='Approved'?button('Continue to test cases →','continueArchitectureTests()',true):'');return appNav()+bpHeading('System architecture','Define your needs, preferred tools and budget, then review the draft.',actions)+'<section class="panel"><div class="panel-title"><h2>Architecture setup</h2>'+badge(d.status)+'</div><form class="form" onsubmit="generateConfiguredArchitecture(event)"><label class="field">Architecture prompt<textarea oninput="changeArchitectureInput(\'prompt\',this.value)" placeholder="Describe traffic, security, availability, integrations and technical constraints">'+esc(d.prompt)+'</textarea></label><div class="architecture-budget-grid"><label class="field">Estimated budget<input type="number" min="0" step="0.01" value="'+esc(d.budget)+'" oninput="changeArchitectureInput(\'budget\',this.value)" placeholder="Optional"></label><label class="field">Currency<select onchange="changeArchitectureInput(\'currency\',this.value)">'+['USD','JPY','BDT'].map(x=>'<option '+(d.currency===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label class="field">Budget covers<select onchange="changeArchitectureInput(\'basis\',this.value)">'+['Monthly infrastructure','Annual infrastructure','Total project implementation'].map(x=>'<option '+(d.basis===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label></div><div class="architecture-tools-summary"><button type="button" onclick="architectureToolsDialog()">Choose tools</button>'+Object.values(d.tools).flat().map(x=>'<span class="badge blue">'+esc(x)+'</span>').join('')+'</div><p class="sub">Your prompt, budget and tools are saved with the generation context. This demo creates an illustrative draft; AI and live cost analysis are not connected.</p><div class="actions" style="justify-content:flex-end"><button class="primary" type="submit">Generate architecture →</button></div></form></section>'+(d.result?'<section class="panel review-panel"><div class="panel-title"><h2>Generated architecture</h2><span class="badge gray">'+(d.status==='Draft'?'Inputs changed · Regenerate':'Illustrative draft')+'</span></div><div class="form"><div class="architecture-budget-grid">'+Object.entries(d.result.components).map(([k,v])=>'<article class="arch-node"><strong>'+k+'</strong><span>'+esc(v)+'</span></article>').join('')+'</div><p style="white-space:pre-wrap">'+esc(architectureState().doc)+'</p></div></section>':'')+'<section class="panel review-panel"><div class="panel-title"><h2>Review feedback</h2></div><div class="form review-comments">'+(d.feedback.length?d.feedback.slice().reverse().map(f=>'<article><strong>'+esc(f.author)+'</strong><small>'+new Date(f.time).toLocaleString()+'</small><p>'+esc(f.text)+'</p></article>').join(''):'<p class="sub">No feedback yet.</p>')+'</div></section>';};
const architectureSnapshotBase=reviewSnapshot;reviewSnapshot=function(route){const data=JSON.parse(architectureSnapshotBase(route));if(route==='architecture')data.architectureSetup=architectureDraft();return JSON.stringify(data);};
Object.assign(localizedLabels,{'Architecture setup':'アーキテクチャ設定','Architecture prompt':'アーキテクチャへの指示','Estimated budget':'想定予算','Currency':'通貨','Budget covers':'予算の対象','Choose tools':'ツールを選択','Choose architecture tools':'アーキテクチャのツールを選択','Apply tools':'ツールを適用','Generate architecture →':'アーキテクチャを生成 →','Generated architecture':'生成されたアーキテクチャ','Disapprove architecture':'アーキテクチャを差し戻す','Monthly infrastructure':'月額インフラ費用','Annual infrastructure':'年間インフラ費用','Total project implementation':'プロジェクト全体の開発費用'});
render();

const architectureViews={};
function architectureView(){return architectureViews[selected] ||= {node:'Backend',zoom:1};}
function archText(en,ja){return interfaceLanguage==='ja'?ja:en;}
const archDescriptions={Frontend:['User interface','ユーザーインターフェース','Presents screens and sends requests to the backend.','画面を表示し、バックエンドにリクエストを送信します。'],Backend:['Application logic','アプリケーションロジック','Validates requests, applies business rules and coordinates data access.','リクエスト検証、業務ルール、データアクセスを処理します。'],Database:['Persistent data','永続データ','Stores project records and application data.','プロジェクト情報とアプリケーションデータを保存します。'],Server:['Hosting environment','ホスティング環境','Hosts the application services and provides compute resources.','アプリケーションを実行するコンピューティング環境です。'],Infrastructure:['Supporting services','補助サービス','Supports deployment, caching and storage according to your selected tools.','選択したツールでデプロイ、キャッシュ、ストレージを支援します。']};
const archEdges=[['Frontend','Backend'],['Backend','Database'],['Server','Backend'],['Backend','Infrastructure']];
function selectArchitectureNode(key){architectureView().node=key;refreshArchitectureExplorer();}
function zoomArchitecture(delta){const v=architectureView();v.zoom=delta===0?1:Math.max(.6,Math.min(1.5,v.zoom+delta));refreshArchitectureExplorer();}
function refreshArchitectureExplorer(){const root=document.getElementById('architectureExplorer');if(root)root.outerHTML=architectureExplorer();}
function architectureExplorer(){const d=architectureDraft(),v=architectureView(),c=d.result.components,k=v.node,desc=archDescriptions[k],jp=interfaceLanguage==='ja';const pos={Frontend:[35,190],Backend:[285,190],Database:[535,190],Server:[285,35],Infrastructure:[285,345]};const connected=archEdges.filter(e=>e.includes(k)).flat().filter(x=>x!==k);return `<section id="architectureExplorer" class="panel architecture-explorer"><div class="panel-title"><div><h2>${archText('Architecture explorer','アーキテクチャビュー')}</h2><p class="sub">${archText('Select a component to explore its role and connections.','コンポーネントを選択して役割と接続を確認できます。')}</p></div><span class="badge blue">${archText('Illustrative draft','参考ドラフト')}</span></div><div class="architecture-workbench"><div class="architecture-canvas-column"><div class="architecture-canvas-toolbar"><span>${archText('System overview','システム概要')}</span><div><button type="button" aria-label="Zoom out" onclick="zoomArchitecture(-.1)">−</button><output>${Math.round(v.zoom*100)}%</output><button type="button" aria-label="Zoom in" onclick="zoomArchitecture(.1)">+</button><button type="button" onclick="zoomArchitecture(0)">${archText('Reset','リセット')}</button></div></div><div class="architecture-viewport"><div style="width:${760*v.zoom}px;height:${475*v.zoom}px"><div class="architecture-map" style="transform:scale(${v.zoom})"><svg viewBox="0 0 760 475" aria-hidden="true"><defs><marker id="archArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#7195cd"/></marker></defs>${archEdges.map(([a,b])=>{let path=a==='Frontend'?'M 225 235 H 285':b==='Database'?'M 475 235 H 535':a==='Server'?'M 380 125 V 190':'M 380 280 V 345';return `<path class="architecture-edge ${a===k||b===k?'is-active':''}" d="${path}" marker-end="url(#archArrow)"/>`;}).join('')}</svg>${Object.entries(pos).map(([key,[x,y]],i)=>`<button type="button" aria-pressed="${key===k}" class="architecture-component ${key===k?'is-selected':''}" style="left:${x}px;top:${y}px" onclick="selectArchitectureNode('${key}')"><span class="architecture-component-top"><span class="architecture-component-icon">${['UI','API','DB','HOST','OPS'][i]}</span><span>${jp?({Frontend:'フロントエンド',Backend:'バックエンド',Database:'データベース',Server:'サーバー',Infrastructure:'インフラ'})[key]:key}</span></span><strong>${esc(c[key])}</strong></button>`).join('')}</div></div></div><div class="architecture-map-caption">${archText('Conceptual connections • Tool choices are shown as supplied','概念的な接続 • 選択されたツールを表示')}</div></div><aside class="architecture-inspector"><span class="badge blue">${archText('Component details','コンポーネント詳細')}</span><h3>${esc(k)}</h3><strong>${esc(c[k])}</strong><h4>${desc[jp?1:0]}</h4><p>${desc[jp?3:2]}</p><h4>${archText('Connected components','接続先')}</h4><div class="architecture-neighbors">${connected.map(n=>`<button onclick="selectArchitectureNode('${n}')">${esc(n)} <span>↗</span></button>`).join('')}</div><div class="architecture-budget-note"><span>${archText('Budget context','予算情報')}</span><strong>${d.result.context.budget===''?archText('Not specified','未設定'):esc(d.result.context.currency+' '+d.result.context.budget)}</strong><small>${esc(d.result.context.basis)}</small></div></aside></div><details class="architecture-spec"><summary>${archText('View architecture notes','アーキテクチャのメモを表示')}</summary><p>${esc(architectureState().doc)}</p></details></section>`;}
const architecturePageBeforeExplorer=blueprintPageRoutes.architecture;
blueprintPageRoutes.architecture=function(){const html=architecturePageBeforeExplorer();if(!selected||!architectureDraft().result)return html;const el=document.createElement('div');el.innerHTML=html;const result=el.querySelector('.review-panel');if(result)result.outerHTML=architectureExplorer();return el.innerHTML;};
render();
